import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    x = int(data[1])
    arr = list(map(int, data[2:2+n]))

    if n == 0:
        print(-1)
        return

    index_map = {}
    for i in range(n):
        val = arr[i]
        if val != 0:
            if x % val == 0:
                complement = x // val
                if complement in index_map:
                    idx1 = index_map[complement] + 1
                    idx2 = i + 1
                    if idx1 > idx2:
                        idx1, idx2 = idx2, idx1
                    print(idx1, idx2)
                    return
        if val not in index_map:
            index_map[val] = i

    # Handle case where product is 0
    if x == 0:
        zero_indices = []
        for i in range(n):
            if arr[i] == 0:
                zero_indices.append(i)
        if len(zero_indices) >= 2:
            print(zero_indices[0] + 1, zero_indices[1] + 1)
            return
        for i in range(n):
            if arr[i] != 0:
                for j in range(i + 1, n):
                    if arr[j] == 0:
                        print(i + 1, j + 1)
                        return

    print(-1)

if __name__ == "__main__":
    main()
